import math

def calculate_grid(count, cols, aspect_ratio):
    if cols <= 0:
        cols = 1
    rows = math.ceil(count / cols)
    return {"rows": rows, "cols": cols, "count": count, "aspect_ratio": aspect_ratio}

def get_cell_position(index, grid):
    col = index % grid["cols"]
    row = index // grid["cols"]
    return row, col

def get_cell_center(row, col, grid, cell_size):
    x = (col - (grid["cols"] - 1) / 2.0) * cell_size
    y = (row - (grid["rows"] - 1) / 2.0) * cell_size
    return x, y

def get_camera_position(grid, cell_size, distance=10.0):
    total_width = grid["cols"] * cell_size
    total_height = grid["rows"] * cell_size
    max_dim = max(total_width, total_height)
    fov = 50.0
    cam_dist = (max_dim / 2.0) / math.tan(math.radians(fov / 2.0)) + distance
    return (0.0, -cam_dist, 0.0)

