import os

def validate_output_path(path):
    if not path:
        return False
    try:
        if not os.path.exists(path):
            os.makedirs(path)
        return os.access(path, os.W_OK)
    except Exception:
        return False

def filter_mesh_objects(objects):
    return [obj for obj in objects if obj.type == 'MESH']
